<?php if (!isset($approvalResult)) { http_response_code(404); exit; } ?>
<?php if (!$approvalResult['ok']): ?><div class="upload-body" role="status">No fue posible cargar las rondas.</div>
<?php elseif ($approvalResult['data']===[]): ?><div class="upload-body">No hay rondas en esta página.</div>
<?php else: ?><div class="table-scroll" tabindex="0" role="region" aria-label="Rondas de aprobación"><table class="data-table"><thead><tr><th>Ronda</th><th>Documento y versión</th><th>Estado</th><th>Decisiones</th><th>Solicitada por</th><th>Acción</th></tr></thead><tbody>
<?php foreach ($approvalResult['data'] as $item): ?><tr><td data-label="Ronda">#<?= e($item['numero_ronda']??'') ?></td><td data-label="Documento y versión"><?= e($item['documento_titulo']??'') ?> · v<?= e($item['numero_version']??'') ?></td><td data-label="Estado"><span class="badge badge-neutral"><?= e(approval_states()[$item['estado']??'']??'Sin estado') ?></span></td><td data-label="Decisiones"><?= e(($item['decisiones_count']??0)-($item['pendientes_count']??0)) ?> de <?= e($item['decisiones_count']??0) ?></td><td data-label="Solicitada por"><?= e($item['solicitada_por']['nombre']??'') ?></td><td data-label="Acción"><a class="table-link" href="<?= e(page_url('aprobacion',['id'=>$item['id']])) ?>"><?= ($item['puede_decidir']??false)?'Revisar y decidir':'Ver detalle' ?></a></td></tr><?php endforeach; ?>
</tbody></table></div><?php endif; ?>
